create table alumno (acta_nacimiento boolean not null, aptitud_fisica boolean not null, birth_date date, constancia6grado boolean not null, constancia_cuil boolean not null, constancia_cuil_tutor boolean not null, constancia_regular boolean not null, deleted boolean not null, dni integer not null, dni_tutor integer not null, estudio_primario_tutor smallint check (estudio_primario_tutor between 0 and 1), estudio_secundario_tutor smallint check (estudio_secundario_tutor between 0 and 1), estudio_ter_univ_tutor smallint check (estudio_ter_univ_tutor between 0 and 1), ficha_inscripcion boolean not null, ficha_medica boolean not null, foto4x4 boolean not null, foto_carnet_vac boolean not null, foto_dni boolean not null, fotocopia_dni_tutor boolean not null, fotocopia_libro_matriz boolean not null, grupo_sanguineo boolean not null, libreta6grado boolean not null, plan_social boolean not null, trabaja boolean not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), localidad_entity_id bigint, parentesco_tutor_entity_id bigint, address varchar(255), apellido_tutor varchar(255), created_by varchar(255), cuil varchar(255), cuil_tutor varchar(255), first_name varchar(255), last_modified_by varchar(255), last_name varchar(255), nombre_tutor varchar(255), telefono1 varchar(255), telefono2 varchar(255), primary key (id));
create table departamento (deleted boolean not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), provincia_id bigint, created_by varchar(255), last_modified_by varchar(255), nombre varchar(255), primary key (id));
create table localidad (deleted boolean not null, created_date timestamp(6), departamento_id bigint, id bigint not null, last_modified_date timestamp(6), created_by varchar(255), last_modified_by varchar(255), nombre varchar(255), primary key (id));
create table menu (deleted boolean not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), code varchar(255), created_by varchar(255), description varchar(255), last_modified_by varchar(255), path varchar(255), primary key (id));
create table menu_role (create_per boolean, delete boolean not null, deleted boolean not null, update boolean not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), menu_id bigint, created_by varchar(255), last_modified_by varchar(255), role varchar(255), primary key (id));
create table parentesco_tutor (deleted boolean not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), created_by varchar(255), descripcion varchar(255), last_modified_by varchar(255), primary key (id));
create table person (deleted boolean not null, dni integer not null, fecha_bautismo date, fecha_confirmacion date, fecha_matrimonio date, fecha_nacimiento date, nro_folio integer not null, nro_libro integer not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), apellido varchar(255), apellido_madrina_baut varchar(255), apellido_madrina_conf varchar(255), apellido_matrimonio varchar(255), apellido_padrino_baut varchar(255), apellido_padrino_conf varchar(255), created_by varchar(255), last_modified_by varchar(255), madre varchar(255), nombre varchar(255), nombre_madrina_baut varchar(255), nombre_madrina_conf varchar(255), nombre_matrimonio varchar(255), nombre_padrino_baut varchar(255), nombre_padrino_conf varchar(255), otras_notas varchar(255), padre varchar(255), primary key (id));
create table person_aud (dni integer, fecha_bautismo date, fecha_confirmacion date, fecha_matrimonio date, fecha_nacimiento date, nro_folio integer, nro_libro integer, rev integer not null, revtype smallint, id bigint not null, apellido varchar(255), apellido_madrina_baut varchar(255), apellido_madrina_conf varchar(255), apellido_matrimonio varchar(255), apellido_padrino_baut varchar(255), apellido_padrino_conf varchar(255), madre varchar(255), nombre varchar(255), nombre_madrina_baut varchar(255), nombre_madrina_conf varchar(255), nombre_matrimonio varchar(255), nombre_padrino_baut varchar(255), nombre_padrino_conf varchar(255), otras_notas varchar(255), padre varchar(255), primary key (rev, id));
create table provincia (deleted boolean not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), created_by varchar(255), last_modified_by varchar(255), nombre varchar(255), primary key (id));
create table revchanges (rev integer not null, entityname varchar(255));
create table revinfo (id integer not null, timestamp bigint not null, username varchar(255), primary key (id));
create table translation (deleted boolean not null, created_date timestamp(6), id bigint not null, last_modified_date timestamp(6), created_by varchar(255), key varchar(255), language varchar(255), last_modified_by varchar(255), namespace varchar(255), value varchar(255), primary key (id));
